const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const montePisano = ee.Geometry.Point(10.51, 43.76).buffer(5000); // Approximate center of Monte Pisano with a 5km buffer
  const startDate = '2019-02-24';
  const endDate = '2019-02-26';

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('VIIRS/001/VNP14IMGTDL_NRT')
    .filterDate(startDate, endDate)
    .filterBounds(montePisano);

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No VIIRS active fire images found for the specified date range and location.");
    console.log("C1");
    return;
  }

  // Select the 'Fire Mask' band.
  // Fire Mask values: 5: Low confidence fire, 6: Medium confidence fire, 7: High confidence fire.
  // We will consider medium or high confidence fires as active fires.
  const fireImages = collection.select('Fire Mask');

  // Create a mosaic of all images to get the maximum fire confidence over the period.
  // Or, more simply, check each image for fire.
  // Let's create a single image where each pixel value is 1 if it's a medium/high confidence fire, 0 otherwise.
  const firePresence = fireImages.map(function(image) {
    return image.gte(6).rename('fire_present');
  }).mosaic(); // Mosaic takes the last image if values overlap, but for boolean, max would be better for presence

  // To check if *any* fire occurred, we can combine all images into one mask.
  const combinedFireMask = fireImages
    .map(image => image.gte(6)) // True if medium/high confidence fire
    .reduce(ee.Reducer.max()) // Take the max value (1 if fire, 0 if not)
    .rename('fire_present');

  // 3. Processing: Calculate the number of fire pixels
  // Scale of 375m is appropriate for VIIRS. Use a slightly larger scale for reduceRegion for performance.
  const scale = 375; // VIIRS resolution is 375m

  const stats = await combinedFireMask.reduceRegion({
    reducer: ee.Reducer.sum(), // Sum of '1's gives the count of fire pixels
    geometry: montePisano,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const firePixelCount = stats['fire_present'];

  if (firePixelCount === null) {
    console.log("Calculation of fire pixels returned null.");
    console.log("C3");
    return;
  }

  console.log(`Total VIIRS images processed: ${collectionSize}`);
  console.log(`Number of medium/high confidence fire pixels detected: ${firePixelCount}`);

  // 5. Validation & Final Answer
  if (firePixelCount > 0) {
    console.log("A"); // Yes, active fire was present
  } else if (firePixelCount === 0) {
    // If no pixels were found, it means no active fire was detected, or no valid pixels with fire.
    // Given the processing, if firePixelCount is 0, it means no fire was detected.
    // If the image itself was all masked out (e.g. by clouds) which resulted in 0 fire pixels,
    // we would check for total valid pixels. But for fire detection, 0 fire pixels directly means no fire.
    console.log("B"); // No active fire was present
  } else {
    console.log("Unexpected calculation result.");
    console.log("C3");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
